function.body:
result_identifier text;
BEGIN
    result_identifier := ad_column_identifier_std(table_name, record_id);
    -- Same scoring as SimSearch.buildIndexedSql: only equality reaches 100, every other name is
    -- capped at 85 so an exact match leads by at least 15 points.
    IF upper(regexp_replace(btrim(result_identifier), '\s+', ' ', 'g'))
       = upper(regexp_replace(btrim(search_term), '\s+', ' ', 'g')) THEN
      RETURN 100::numeric;
    END IF;
    RETURN LEAST(85, GREATEST(SIMILARITY(result_identifier, search_term),
                              0.8 * WORD_SIMILARITY(search_term, result_identifier)) * 100)::numeric;
END ETCOTP_SIM_SEARCH
